-- =====================================================================================
--  Report_QA_E2E_ITEM_LABELS_Layout.sql  -  generated by ERP Studio (report designer, rf-report/1)
--  Report: QA item labels (A4 3x8)
--  Saves the default JSON layout (Scope = 'all') into Sys_ReportLayouts. Safe to run many times.
--  Needs: Database/Phase7_Reports.sql and Database/Phase10_Reports_Json.sql.
-- =====================================================================================
SET NOCOUNT ON;

IF OBJECT_ID(N'dbo.Sys_Reports', N'U') IS NULL OR OBJECT_ID(N'dbo.Sys_ReportLayouts', N'U') IS NULL OR COL_LENGTH(N'dbo.Sys_ReportLayouts', N'LayoutJson') IS NULL
BEGIN
    RAISERROR(N'Sys_Reports / Sys_ReportLayouts.LayoutJson not found - run Phase7_Reports.sql and Phase10_Reports_Json.sql first. Nothing changed.', 16, 1);
    RETURN;
END

DECLARE @Code NVARCHAR(100) = N'QA_E2E_ITEM_LABELS';
DECLARE @NameA NVARCHAR(200) = N'ملصقات أصناف QA (A4 3×8)';
DECLARE @NameE NVARCHAR(200) = N'QA item labels (A4 3x8)';
DECLARE @By NVARCHAR(100) = N'Studio:studio_test';
DECLARE @Json NVARCHAR(MAX) = N'{"schema":"rf-report/1","code":"QA_E2E_ITEM_LABELS","nameAr":"ملصقات أصناف QA (A4 3×8)","nameEn":"QA item labels (A4 3x8)","kind":"labels","page":{"size":"LabelA4_3x8","dir":"auto"},"data":{"source":{"type":"proc","name":"dbo.QA_E2E_Rpt_ItemLabels"},"params":[{"name":"CategoryID","from":"filter","value":"CategoryID"},{"name":"TypeID","from":"filter","value":"TypeID"}],"tables":{"Data":"lines"}},"styles":{"base":{"size":8,"color":"#000000"}},"bands":[{"type":"detail","table":"lines","layout":"labels","labels":{"columns":3,"rows":8,"width":70,"height":37,"gapX":0,"gapY":0,"copies":"Copies","outline":true},"style":{"align":"center","padding":2},"elements":[{"type":"text","text":"{{Company.CompNameA}}","style":{"size":6.5,"color":"#475569","align":"center","nowrap":true}},{"type":"expression","expr":"coalesce(ItemName, NameItem)","style":{"size":8.5,"bold":true,"align":"center","nowrap":true}},{"type":"barcode","value":"coalesce(Barcode, ItemCode)","format":"EAN13","barHeight":11,"showText":true},{"type":"expression","expr":"coalesce(Price, UnitPrice)","format":"n2","label":{"ar":"السعر","en":"Price"},"style":{"size":9,"bold":true,"align":"center"}}]}]}';

BEGIN TRY
    BEGIN TRANSACTION;

    -- 1) report definition (only when it is new; an existing definition is not changed)
    IF NOT EXISTS (SELECT 1 FROM dbo.Sys_Reports WHERE ReportCode = @Code)
    BEGIN
        INSERT INTO dbo.Sys_Reports (ReportCode, NameA, NameE, Kind, ProcName, IsActive)
        VALUES (@Code, @NameA, @NameE, 'list', N'dbo.QA_E2E_Rpt_ItemLabels', 1);
        INSERT INTO dbo.Sys_ReportParams (ReportCode, ParamName, Source, SourceValue, SortOrder)
        VALUES (@Code, N'CategoryID', 'filter', N'CategoryID', 0);
        INSERT INTO dbo.Sys_ReportParams (ReportCode, ParamName, Source, SourceValue, SortOrder)
        VALUES (@Code, N'TypeID', 'filter', N'TypeID', 1);
    END

    -- 2) default JSON layout for everybody (company/branch layouts are managed from the Studio, not here)
    IF EXISTS (SELECT 1 FROM dbo.Sys_ReportLayouts WHERE ReportCode = @Code AND Scope = 'all' AND LayoutFormat = 'json')
        UPDATE dbo.Sys_ReportLayouts
           SET LayoutJson = @Json, PaperSize = 'LabelA4_3x8', Orientation = 'portrait', IsDefault = 1, UpdatedAt = GETDATE(), UpdatedBy = @By
         WHERE ReportCode = @Code AND Scope = 'all' AND LayoutFormat = 'json';
    ELSE
        INSERT INTO dbo.Sys_ReportLayouts (ReportCode, Scope, CompCode, BranchCode, PaperSize, Orientation, LayoutFormat, LayoutJson, IsDefault, UpdatedAt, UpdatedBy)
        VALUES (@Code, 'all', NULL, NULL, 'LabelA4_3x8', 'portrait', 'json', @Json, 1, GETDATE(), @By);

    COMMIT TRANSACTION;
    PRINT N'Report layout saved: ' + @Code;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    DECLARE @Err NVARCHAR(4000) = ERROR_MESSAGE();
    RAISERROR(@Err, 16, 1);
END CATCH
